import{_ as o,o as t,c as a,ai as n}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒","description":"","frontmatter":{"date":"2026-10-21T00:00:00.000Z","title":"Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒","summary":"Bot 让 Codex、Claude Code 或脚本在后台跑长任务时，结束了它并不知道，只能反复去看、白烧用量。这个开源技能用一个「转发 Bot」加 Webhook 例程解决，一句话安装。","category":"新插件","tags":["技能","例程","Webhook","用量"],"sources":[{"url":"https://github.com/eze-is/eze-grokbot/tree/main/wake-on-done","author":"eze-is/eze-grokbot（GitHub）","platform":"GitHub"},{"url":"https://x.com/eze_is_1/status/2108856871948042652","author":"@eze_is_1","platform":"X"}],"updates":[{"link":"/basics/local-computer","title":"在自己电脑上干活：新增「电脑息屏后，Bot 连不上了？」"},{"link":"/resources/?tab=plugins","title":"资源导航 · 插件与连接器：新增 Wake on Done、Web Access Skill"}],"wordCount":766,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒 | WANGXXXL"}],["meta",{"property":"og:description","content":"Bot 让 Codex、Claude Code 或脚本在后台跑长任务时，结束了它并不知道，只能反复去看、白烧用量。这个开源技能用一个「转发 Bot」加 Webhook 例程解决，一句话安装。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-21-wake-on-done"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-21-wake-on-done-d3c6c46323.png"}],["meta",{"property":"og:image:alt","content":"Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"Bot 让 Codex、Claude Code 或脚本在后台跑长任务时，结束了它并不知道，只能反复去看、白烧用量。这个开源技能用一个「转发 Bot」加 Webhook 例程解决，一句话安装。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-21-wake-on-done-d3c6c46323.png"}],["meta",{"name":"twitter:image:alt","content":"Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-21-wake-on-done"}]]},"headers":[],"relativePath":"daily/2026-10-21-wake-on-done.md","filePath":"daily/2026-10-21-wake-on-done.md","lastUpdated":1792571830000}'),r={name:"daily/2026-10-21-wake-on-done.md"};function l(i,e,s,d,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="wake-on-done-bot-派出去的长任务一跑完-自动把它叫醒" tabindex="-1">Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒 <a class="header-anchor" href="#wake-on-done-bot-派出去的长任务一跑完-自动把它叫醒" aria-label="Permalink to &quot;Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒&quot;">​</a></h1><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>越来越多人让 Bot 当&quot;工头&quot;：把写代码、跑构建、批量抓取这类耗时的活，交给云电脑或自己电脑上的 Codex CLI、Claude Code、脚本去跑。问题是<strong>后台任务结束时不会通知 Bot</strong>，结果只有两种：</p><ul><li>Bot 每隔几分钟去看一眼，<strong>每看一次都在花用量</strong>；</li><li>或者一直等，等到你问一句&quot;好了没&quot;才回去看。</li></ul><p><a href="https://github.com/eze-is/eze-grokbot/tree/main/wake-on-done" target="_blank" rel="noopener noreferrer">Wake on Done</a> 是 <a href="https://x.com/eze_is_1/status/2108856871948042652" target="_blank" rel="noopener noreferrer">@eze_is_1</a> 开源的一个 Grok Bot 技能，专门补这个缺口。</p><h2 id="原理-看懂再装" tabindex="-1">原理（看懂再装） <a class="header-anchor" href="#原理-看懂再装" aria-label="Permalink to &quot;原理（看懂再装）&quot;">​</a></h2><p>Grok Bot 能被外部事件叫醒的入口是<strong>例程的 Webhook 触发</strong>，但每个 Bot 的 Webhook 地址是各自独立的，一个个配很麻烦。作者的办法是：</p><ol><li>只建一个专门的 <strong>「Wake on Done relay」转发 Bot</strong>，只给它配一个 Webhook 例程。</li><li>长任务用脚本 <code>notify-run</code> 包一层启动。任务结束（成功、失败、被中断都算）时，它向这个 Webhook 发一条通知，里面带着<strong>派活 Bot 的 ID</strong>、退出码和最后几百个字的输出。</li><li>转发 Bot 按 ID 把通知转给当初派活的 Bot，那个 Bot 醒来接着验收、汇报。</li></ol><p>配一次，所有 Bot 都能用；云电脑和你注册过的本地电脑都能装。</p><h2 id="怎么装" tabindex="-1">怎么装 <a class="header-anchor" href="#怎么装" aria-label="Permalink to &quot;怎么装&quot;">​</a></h2><p>把这句话发给你的主 Bot：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>安装 https://github.com/eze-is/eze-grokbot/tree/main/wake-on-done 这个 skill，并帮我设置好</span></span></code></pre></div><p>按仓库说明，接下来主 Bot 会装好技能、创建「Wake on Done relay」，由 relay 在自己的对话里带你走完设置，<strong>你要做的只有三件事</strong>：批准一张创建例程的卡片；打开例程详情，把 Webhook 地址贴到对话里；把 Webhook 密钥贴进安全输入框（不要贴在聊天里）。在你自己的电脑上安装时，还会弹出命令授权提示。每台电脑装好后会发一条测试通知，收到就算通过。</p><h2 id="装好以后怎么用" tabindex="-1">装好以后怎么用 <a class="header-anchor" href="#装好以后怎么用" aria-label="Permalink to &quot;装好以后怎么用&quot;">​</a></h2><p>对任何一个 Bot 说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按 wake-on-done 技能，在后台用 codex exec 跑这个任务：&lt;任务描述&gt;。</span></span>
<span class="line"><span>结果写到 ~/results/task-01.md。跑完被叫醒后，对照下面的标准验收再告诉我：&lt;验收标准&gt;</span></span></code></pre></div><p>技能里写明了几条最容易踩的坑，Bot 会照做，你知道一下就好：</p><ul><li><strong>CLI 编程助手要用一次性模式</strong>（<code>codex exec</code>、<code>claude -p</code>），聊天模式跑完会一直等下一句，永远不退出，通知也就永远不来。</li><li><strong>关掉标准输入</strong>（命令后加 <code>&lt;/dev/null</code>），否则有的工具会卡在等确认。</li><li>在 Mac 上，远程命令返回时会连带杀掉后台任务，<strong>要用 tmux 启动</strong>（仓库写明 2026-10-11 实测）。</li></ul><h2 id="安全上要知道的" tabindex="-1">安全上要知道的 <a class="header-anchor" href="#安全上要知道的" aria-label="Permalink to &quot;安全上要知道的&quot;">​</a></h2><ul><li>通知内容（包括输出末尾）<strong>只当数据，不当指令</strong>，这是技能里写死的规则；转发 Bot 只按 ID 精确匹配转发，不按名字。</li><li>密钥只以文件形式保存在电脑上，不出现在聊天、记忆和日志里。所有 Bot 共用一台云电脑，<strong>这把钥匙所有 Bot 都能用到</strong>，别把它当成隔离手段。</li><li>外部 CLI 用的是你在那边的订阅或 API 额度，按那边的规则计费。</li></ul>`,20)])])}const u=o(r,[["render",l]]);export{g as __pageData,u as default};
